fn check_all_lowercase(v: &Vec<char>) -> bool {
    // Input is "all lowercase" if length > 0 and every char is in 'a'..='z'
    if v.is_empty() {
        return false;
    }
    v.iter().all(|&c| c >= 'a' && c <= 'z')
}

fn solve(input: Vec<char>) -> Vec<char> {
    if check_all_lowercase(&input) {
        vec!['a']
    } else {
        vec!['A']
    }
}